55: // EnsureRepoLayout creates the <repoRoot>/.memory directory structure and its subdirectories:
56: // claims, events/reviews, events/answers, views/index, views/subsystems, .cache.
57: // It also ensures a .gitignore exists ignoring .cache/.
58: // It is idempotent.
59: func EnsureRepoLayout(repoRoot string) error {
60: 	if repoRoot == "" {
61: 		repoRoot = "."
