72: 	gitignorePath := filepath.Join(memoryDir, ".gitignore")
73: 	if _, err := os.Stat(gitignorePath); os.IsNotExist(err) {
74: 		content := []byte(".cache/\n")
75: 		if err := os.WriteFile(gitignorePath, content, 0644); err != nil {
76: 			return fmt.Errorf("creating gitignore in %s: %w", memoryDir, err)
77: 		}
78: 	}
