103: // RecordGap records a step gap interval [start, end] into the header.
104: func (h *Header) RecordGap(start, end int) {
105: 	if start <= end {
106: 		h.StepGaps = append(h.StepGaps, [2]int{start, end})
107: 	}
108: }
109: 
110: // RecordGaps inspects steps, detects missing step index intervals, and appends them to StepGaps.
111: func (h *Header) RecordGaps(steps []harness.Step) {
112: 	gaps := DetectGaps(steps)
113: 	if len(gaps) == 0 {
114: 		return
115: 	}
116: 	existing := make(map[[2]int]bool, len(h.StepGaps))
117: 	for _, g := range h.StepGaps {
118: 		existing[g] = true
119: 	}
120: 	for _, g := range gaps {
121: 		if !existing[g] {
122: 			h.StepGaps = append(h.StepGaps, g)
123: 			existing[g] = true
124: 		}
125: 	}
126: }
127: 
128: // Gaps returns the header's step gaps as typed StepGap values.
129: func (h *Header) Gaps() []StepGap {
130: 	res := make([]StepGap, len(h.StepGaps))
131: 	for i, g := range h.StepGaps {
132: 		res[i] = StepGap(g)
133: 	}
134: 	return res
135: }
136: 
137: // HasGaps returns true if any step gaps are recorded.
138: func (h *Header) HasGaps() bool {
139: 	return len(h.StepGaps) > 0
140: }
141: 
142: // TotalMissingSteps returns the total count of missing step indices across all gaps.
143: func (h *Header) TotalMissingSteps() int {
144: 	total := 0
145: 	for _, g := range h.StepGaps {
146: 		if g[1] >= g[0] {
147: 			total += (g[1] - g[0] + 1)
148: 		}
149: 	}
150: 	return total
151: }
