153: // RecordCommit appends a commit hash to the header's Commits list if not already present.
154: func (h *Header) RecordCommit(sha string) {
155: 	sha = strings.TrimSpace(sha)
156: 	if sha == "" {
157: 		return
158: 	}
159: 	for _, c := range h.Commits {
160: 		if strings.EqualFold(c, sha) {
161: 			return
162: 		}
163: 	}
164: 	h.Commits = append(h.Commits, sha)
165: }
166: 
167: // RecordCommits appends multiple commit hashes to the header's Commits list, ignoring duplicates.
168: func (h *Header) RecordCommits(commits []string) {
169: 	for _, c := range commits {
170: 		h.RecordCommit(c)
171: 	}
172: }
