179: // HasCommit returns true if the specific commit hash is recorded in the header.
180: func (h *Header) HasCommit(sha string) bool {
181: 	sha = strings.TrimSpace(sha)
182: 	if sha == "" {
183: 		return false
184: 	}
185: 	for _, c := range h.Commits {
186: 		if strings.EqualFold(c, sha) {
187: 			return true
188: 		}
189: 	}
190: 	return false
191: }
