210: // UnmarshalJSON implements custom JSON unmarshaling for Header to handle flexible timestamp formats
211: // and flexible commit formats.
212: func (h *Header) UnmarshalJSON(data []byte) error {
213: 	type Alias Header
214: 	aux := &struct {
215: 		Started any `json:"started"`
216: 		Ended   any `json:"ended"`
217: 		Commits any `json:"commits"`
218: 		*Alias
219: 	}{
220: 		Alias: (*Alias)(h),
221: 	}
222: 
223: 	if err := json.Unmarshal(data, &aux); err != nil {
224: 		return err
225: 	}
226: 
227: 	if aux.Started != nil {
228: 		t, err := parseTimeFlexible(aux.Started)
229: 		if err != nil {
230: 			return fmt.Errorf("parsing started timestamp: %w", err)
231: 		}
232: 		h.Started = t
233: 	}
234: 
235: 	if aux.Ended != nil {
236: 		t, err := parseTimeFlexible(aux.Ended)
237: 		if err != nil {
238: 			return fmt.Errorf("parsing ended timestamp: %w", err)
239: 		}
240: 		h.Ended = t
241: 	}
242: 
243: 	if aux.Commits != nil {
244: 		commits, err := parseCommitsFlexible(aux.Commits)
245: 		if err != nil {
246: 			return fmt.Errorf("parsing commits: %w", err)
247: 		}
248: 		h.Commits = commits
249: 	}
250: 
251: 	return nil
252: }
