254: func parseTimeFlexible(val any) (time.Time, error) {
255: 	if val == nil {
256: 		return time.Time{}, nil
257: 	}
258: 	switch v := val.(type) {
259: 	case string:
260: 		v = strings.TrimSpace(v)
261: 		if v == "" || v == "null" {
262: 			return time.Time{}, nil
263: 		}
264: 		if t, err := time.Parse(time.RFC3339Nano, v); err == nil {
265: 			return t.UTC(), nil
266: 		}
267: 		if t, err := time.Parse(time.RFC3339, v); err == nil {
268: 			return t.UTC(), nil
269: 		}
270: 		for _, layout := range []string{
271: 			"2006-01-02T15:04:05",
272: 			"2006-01-02 15:04:05",
273: 			"2006-01-02",
274: 		} {
275: 			if t, err := time.Parse(layout, v); err == nil {
276: 				return t.UTC(), nil
277: 			}
278: 		}
279: 		return time.Time{}, fmt.Errorf("unrecognized time format %q", v)
280: 	case float64:
281: 		if v == 0 {
282: 			return time.Time{}, nil
283: 		}
284: 		if v > 1e11 {
285: 			return time.UnixMilli(int64(v)).UTC(), nil
286: 		}
287: 		return time.Unix(int64(v), 0).UTC(), nil
288: 	default:
289: 		return time.Time{}, fmt.Errorf("unexpected time type %T", val)
290: 	}
291: }
292: 
293: func parseCommitsFlexible(val any) ([]string, error) {
294: 	if val == nil {
295: 		return nil, nil
296: 	}
297: 	switch v := val.(type) {
298: 	case string:
299: 		v = strings.TrimSpace(v)
300: 		if v == "" || v == "null" {
301: 			return nil, nil
302: 		}
303: 		parts := strings.FieldsFunc(v, func(r rune) bool {
304: 			return r == ',' || r == ' ' || r == '\t' || r == '\n'
305: 		})
306: 		var result []string
307: 		for _, p := range parts {
308: 			p = strings.TrimSpace(p)
309: 			if p != "" {
310: 				result = append(result, p)
311: 			}
312: 		}
313: 		return result, nil
314: 	case []any:
315: 		var result []string
316: 		for _, item := range v {
317: 			switch it := item.(type) {
318: 			case string:
319: 				it = strings.TrimSpace(it)
320: 				if it != "" {
321: 					result = append(result, it)
322: 				}
323: 			case map[string]any:
324: 				for _, key := range []string{"sha", "commit", "hash", "ref"} {
325: 					if s, ok := it[key].(string); ok {
326: 						s = strings.TrimSpace(s)
327: 						if s != "" {
328: 							result = append(result, s)
329: 							break
330: 						}
331: 					}
332: 				}
333: 			}
334: 		}
335: 		return result, nil
336: 	case []string:
337: 		var result []string
338: 		for _, s := range v {
339: 			s = strings.TrimSpace(s)
340: 			if s != "" {
341: 				result = append(result, s)
342: 			}
343: 		}
344: 		return result, nil
345: 	default:
346: 		return nil, fmt.Errorf("unexpected commits type %T", val)
347: 	}
348: }
