522: // WriteEpisode writes an episode and returns its final destination path.
523: func (s *Store) WriteEpisode(ep *Episode) (string, error) {
524: 	if ep == nil {
525: 		return "", ErrNilEpisode
526: 	}
527: 	if ep.Header.SessionID == "" {
528: 		return "", ErrEmptySessionID
529: 	}
530: 	if err := validateSessionID(ep.Header.SessionID); err != nil {
531: 		return "", err
532: 	}
533: 
534: 	// Fill defaults if unset
535: 	if ep.Header.EpisodeID == "" {
536: 		ep.Header.EpisodeID = NewEpisodeID()
537: 	}
538: 	if ep.Header.RepoID == "" && s.repoID != "" {
539: 		ep.Header.RepoID = s.repoID
540: 	}
541: 	if ep.Header.PipelineVersion == "" {
542: 		ep.Header.PipelineVersion = DefaultPipelineVersion
543: 	}
544: 	if ep.Header.CompactorVersion == "" {
545: 		ep.Header.CompactorVersion = DefaultCompactorVersion
546: 	}
547: 	if len(ep.Header.StepGaps) == 0 && len(ep.Steps) > 1 {
548: 		ep.Header.RecordGaps(ep.Steps)
549: 	}
550: 
551: 	targetPath := s.EpisodePath(ep)
552: 	dir := filepath.Dir(targetPath)
553: 	if err := os.MkdirAll(dir, 0755); err != nil {
554: 		return "", fmt.Errorf("creating directory %s: %w", dir, err)
555: 	}
556: 
557: 	tmpFile, err := os.CreateTemp(dir, fmt.Sprintf(".%s-*.tmp", ep.Header.SessionID))
558: 	if err != nil {
559: 		return "", fmt.Errorf("creating temp file in %s: %w", dir, err)
560: 	}
561: 	tmpName := tmpFile.Name()
562: 	success := false
563: 	defer func() {
564: 		if !success {
565: 			_ = tmpFile.Close()
566: 			_ = os.Remove(tmpName)
567: 		}
568: 	}()
569: 
570: 	enc, err := zstd.NewWriter(tmpFile, zstd.WithEncoderLevel(zstd.SpeedDefault))
571: 	if err != nil {
572: 		return "", fmt.Errorf("creating zstd encoder: %w", err)
573: 	}
574: 
575: 	// Line 1: Header line
576: 	headerBytes, err := json.Marshal(ep.Header)
577: 	if err != nil {
578: 		_ = enc.Close()
579: 		return "", fmt.Errorf("marshaling episode header: %w", err)
580: 	}
581: 	if _, err := enc.Write(append(headerBytes, '\n')); err != nil {
582: 		_ = enc.Close()
583: 		return "", fmt.Errorf("writing episode header: %w", err)
584: 	}
585: 
586: 	// Step lines
587: 	for i, step := range ep.Steps {
588: 		stepBytes, err := json.Marshal(step)
589: 		if err != nil {
590: 			_ = enc.Close()
591: 			return "", fmt.Errorf("marshaling step %d: %w", i, err)
592: 		}
593: 		if _, err := enc.Write(append(stepBytes, '\n')); err != nil {
594: 			_ = enc.Close()
595: 			return "", fmt.Errorf("writing step %d: %w", i, err)
596: 		}
597: 	}
598: 
599: 	if err := enc.Close(); err != nil {
600: 		return "", fmt.Errorf("closing zstd encoder: %w", err)
601: 	}
602: 
603: 	if err := tmpFile.Close(); err != nil {
604: 		return "", fmt.Errorf("closing temp file: %w", err)
605: 	}
606: 
607: 	if err := os.Rename(tmpName, targetPath); err != nil {
608: 		return "", fmt.Errorf("committing episode file to %s: %w", targetPath, err)
609: 	}
610: 
611: 	success = true
612: 	return targetPath, nil
613: }
