617: func (s *Store) Read(sessionID string, year ...int) (*Episode, error) {
618: 	if err := validateSessionID(sessionID); err != nil {
619: 		return nil, err
620: 	}
621: 	if len(year) > 0 && year[0] > 0 {
622: 		path := s.Path(sessionID, year[0])
623: 		return s.ReadFromPath(path)
624: 	}
625: 	path, err := s.FindPath(sessionID)
626: 	if err != nil {
627: 		return nil, err
628: 	}
629: 	return s.ReadFromPath(path)
630: }
