632: // ReadHeader reads only the metadata header from an episode file without reading all steps.
633: func (s *Store) ReadHeader(sessionID string, year ...int) (*Header, error) {
634: 	if err := validateSessionID(sessionID); err != nil {
635: 		return nil, err
636: 	}
637: 	if len(year) > 0 && year[0] > 0 {
638: 		path := s.Path(sessionID, year[0])
639: 		return s.ReadHeaderFromPath(path)
640: 	}
641: 	path, err := s.FindPath(sessionID)
642: 	if err != nil {
643: 		return nil, err
644: 	}
645: 	return s.ReadHeaderFromPath(path)
