import json, re

def parse_checkpoint(content):
    sections = {}
    canonical = [
        "Outstanding User Requests",
        "User Knowledge",
        "Work Accomplished",
        "Model Knowledge",
        "Files and Code",
        "Current Work and Next Steps",
        "Current Work",
    ]
    lines = content.splitlines()
    curr_section = None
    curr_lines = []

    def normalize_header(h):
        h = re.sub(r"^[#\s]+", "", h)
        h = re.sub(r"^\d+[\.\)]\s*", "", h).strip()
        return h

    def is_major_header(line):
        line_s = line.strip()
        if not line_s.startswith("#"):
            return None
        h = normalize_header(line_s)
        for c in canonical:
            if h.lower() == c.lower() or h.lower().startswith(c.lower()):
                # map "Current Work and Next Steps" to "Current Work" as canonical too
                return c
        # Also check for ## Header
        if line_s.startswith("## ") and not line_s.startswith("### "):
            return h
        return None

    for line in lines:
        if line.strip().startswith("# Conversation Logs") or line.strip().startswith("**IMPORTANT:"):
            if curr_section:
                sections[curr_section] = "\n".join(curr_lines).strip()
                curr_section = None
                curr_lines = []
            break
        header = is_major_header(line)
        if header:
            if curr_section:
                sections[curr_section] = "\n".join(curr_lines).strip()
                curr_lines = []
            curr_section = header
        elif curr_section:
            curr_lines.append(line)

    if curr_section:
        sections[curr_section] = "\n".join(curr_lines).strip()

    # Also map "Current Work and Next Steps" to "Current Work" if "Current Work" not present
    if "Current Work and Next Steps" in sections and "Current Work" not in sections:
        sections["Current Work"] = sections["Current Work and Next Steps"]

    return sections

with open("/Users/mcneillm/.gemini/antigravity/brain/adca24bc-8e08-4e92-8604-17ca3b791efc/.system_generated/logs/transcript_full.jsonl") as f:
